#!/usr/bin/env python3
"""Read a tj.py capture transcript on stdin and collapse runs of blank/duplicate
padding lines so output is compact. Keeps lines verbatim otherwise."""
import sys, re

def is_pad(l):
    # a line whose content between popup borders is all spaces AND is part of a run
    s = l.rstrip()
    core = re.sub(r'[│┌┐└┘─█▲▼ ]', '', s)
    return core == ''

lines = sys.stdin.read().split('\n')
out = []
run = 0
for l in lines:
    if is_pad(l):
        run += 1
        if run <= 1:
            out.append(l)
        elif run == 2:
            out.append('    ... [%d-th padding line; identical pattern repeats] ...' % run)
    else:
        run = 0
        out.append(l)
print('\n'.join(out))

#!/usr/bin/env python3
"""Persistent tmux driver.
  drive.py start SESS COLS ROWS [DATASET]   -> fresh home from /tmp/h_fsfA template
  drive.py send  SESS KEYS...               -> send keys (same syntax as tj.py), final capture
  drive.py sendE SESS KEYS...               -> same but capture with escapes
  drive.py cap   SESS
  drive.py kill  SESS
"""
import os, sys, subprocess, time, shutil

EXE = "/workspace/executable"

def sh(*a):
    return subprocess.run(a, capture_output=True, text=True)

def start(sess, cols, rows, dataset="/tmp/h_fsfA/tui-journal"):
    home = f"/tmp/h_{sess}"
    shutil.rmtree(home, ignore_errors=True)
    os.makedirs(home)
    if dataset != "NONE":
        shutil.copytree(dataset, home + "/tui-journal")
    sh("tmux", "kill-session", "-t", sess)
    time.sleep(0.2)
    args = f"-b json -j {home}/tui-journal/entries.json" if dataset != "NONE" else ""
    cmd = (f"env HOME='{home}' TERM='xterm-256color' {EXE} {args}; "
           f"echo __TJEXIT_$?__; sleep 3000")
    r = sh("tmux", "new-session", "-d", "-s", sess, "-x", str(cols), "-y", str(rows), cmd)
    if r.returncode:
        print("NEWSESS FAIL", r.stderr); sys.exit(1)
    time.sleep(1.0)

def send(sess, keys, esc=False):
    n = 0
    for k in keys:
        if k in ("@cap", "@capE"):
            n += 1
            print(f"===== CAPTURE {n} =====")
            print(cap(sess, esc=(k == "@capE") or esc))
            print(f"===== /CAPTURE {n} =====")
        elif k.startswith("@s"):
            time.sleep(float(k[2:]))
        elif k.startswith("^"):
            sh("tmux", "send-keys", "-t", sess, k[1:]); time.sleep(0.28)
        else:
            sh("tmux", "send-keys", "-t", sess, "-l", k); time.sleep(0.28)

def cap(sess, esc=False):
    a = ["tmux", "capture-pane", "-p", "-t", sess]
    if esc:
        a.insert(2, "-e")
    return sh(*a).stdout.rstrip("\n")

if __name__ == "__main__":
    cmd = sys.argv[1]
    sess = sys.argv[2]
    if cmd == "start":
        start(sess, sys.argv[3], sys.argv[4], sys.argv[5] if len(sys.argv) > 5 else "/tmp/h_fsfA/tui-journal")
        print(cap(sess))
    elif cmd in ("send", "sendE"):
        send(sess, sys.argv[3:], esc=(cmd == "sendE"))
        print("===== FINAL =====")
        print(cap(sess, esc=(cmd == "sendE")))
    elif cmd == "cap":
        print(cap(sess))
    elif cmd == "capE":
        print(cap(sess, esc=True))
    elif cmd == "kill":
        sh("tmux", "kill-session", "-t", sess)
